class Solution {
public:
    vector<vector<string>> groupAnagrams(vector<string>& strs) {
        // 排序后的字符串作为同组异位词的公共键
        unordered_map<string, vector<string>> groups;
        for (auto& s : strs) {
            string key = s;
            sort(key.begin(), key.end());
            groups[key].push_back(move(s));
        }
        vector<vector<string>> ans;
        for (auto& [_, group] : groups) ans.push_back(move(group));
        return ans;
    }
};

class Solution {
public:
    int longestConsecutive(vector<int>& nums) {
        unordered_set<int> st(nums.begin(), nums.end());
        int ans = 0;
        for (int x : st) {
            if (st.count(x - 1)) continue; // x 不是序列起点，跳过
            int len = 1;                   // 从起点向后数完整段
            while (st.count(x + len)) ++len;
            ans = max(ans, len);
        }
        return ans;
    }
};

class Solution {
public:
    void moveZeroes(vector<int>& nums) {
        int slow = 0; // 不变量：[0, slow) 均为按原序排列的非零数
        for (int fast = 0; fast < (int)nums.size(); ++fast) {
            if (nums[fast] != 0) {
                swap(nums[slow++], nums[fast]);
            }
        }
    }
};

class Solution {
public:
    int maxArea(vector<int>& height) {
        int ans = 0, l = 0, r = (int)height.size() - 1;
        while (l < r) {
            ans = max(ans, min(height[l], height[r]) * (r - l));
            // 宽度在变小，只有丢掉较矮的板、换成更高的板才可能更优
            if (height[l] < height[r]) ++l;
            else --r;
        }
        return ans;
    }
};

class Solution {
public:
    vector<vector<int>> threeSum(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        vector<vector<int>> ans;
        for (int i = 0; i < n - 2; ++i) {
            if (nums[i] > 0) break;                        // 最小的数已为正，无解
            if (i > 0 && nums[i] == nums[i - 1]) continue; // 固定数去重
            int l = i + 1, r = n - 1;
            while (l < r) {
                int sum = nums[i] + nums[l] + nums[r];
                if (sum < 0) ++l;
                else if (sum > 0) --r;
                else {
                    ans.push_back({nums[i], nums[l], nums[r]});
                    while (l < r && nums[l] == nums[l + 1]) ++l; // 解内去重
                    while (l < r && nums[r] == nums[r - 1]) --r;
                    ++l; --r;
                }
            }
        }
        return ans;
    }
};

class Solution {
public:
    int trap(vector<int>& height) {
        int ans = 0, l = 0, r = (int)height.size() - 1;
        int preMax = 0, sufMax = 0; // 两侧已扫过部分的最大高度
        while (l < r) {
            preMax = max(preMax, height[l]);
            sufMax = max(sufMax, height[r]);
            if (preMax < sufMax) {            // 左端水位由 preMax 唯一确定
                ans += preMax - height[l++];
            } else {
                ans += sufMax - height[r--];
            }
        }
        return ans;
    }
};

class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        int cnt[128] = {};                 // 窗口内每个字符的出现次数
        int ans = 0, left = 0;
        for (int right = 0; right < (int)s.size(); right++) {
            cnt[s[right]]++;               // s[right] 进入窗口
            while (cnt[s[right]] > 1) {    // 出现重复，收缩左端直到去掉重复
                cnt[s[left++]]--;
            }
            ans = max(ans, right - left + 1);
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> findAnagrams(string s, string p) {
        int n = s.size(), m = p.size();
        if (n < m) return {};
        vector<int> need(26), win(26), ans;
        for (char c : p) need[c - 'a']++;
        for (int i = 0; i < n; i++) {
            win[s[i] - 'a']++;                  // s[i] 进窗
            if (i >= m) win[s[i - m] - 'a']--;  // 长度超过 m，最左字符出窗
            if (i >= m - 1 && win == need)      // 窗口恰好 m 个字符时比较
                ans.push_back(i - m + 1);
        }
        return ans;
    }
};

class Solution {
public:
    int subarraySum(vector<int>& nums, int k) {
        unordered_map<int, int> cnt{{0, 1}};  // 前缀和 -> 出现次数，空前缀记 0:1
        int sum = 0, ans = 0;
        for (int x : nums) {
            sum += x;
            if (auto it = cnt.find(sum - k); it != cnt.end())
                ans += it->second;  // 有这么多个前缀和为 sum-k 的位置
            cnt[sum]++;
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& nums, int k) {
        vector<int> ans;
        deque<int> dq;  // 存下标，对应值单调递减，队头即窗口最大值
        for (int i = 0; i < (int)nums.size(); i++) {
            while (!dq.empty() && nums[dq.back()] <= nums[i])
                dq.pop_back();  // 被弹者更小且更早过期，不可能再成为答案
            dq.push_back(i);
            if (dq.front() <= i - k) dq.pop_front();  // 队头滑出窗口
            if (i >= k - 1) ans.push_back(nums[dq.front()]);
        }
        return ans;
    }
};

class Solution {
public:
    string minWindow(string s, string t) {
        unordered_map<char, int> need, win;
        for (char c : t) need[c]++;
        int left = 0, valid = 0, start = 0, minLen = INT_MAX;
        for (int right = 0; right < (int)s.size(); right++) {
            char c = s[right];
            if (need.count(c)) {                     // 只关心 t 中出现的字符
                if (++win[c] == need[c]) valid++;    // 该字符恰好凑齐
            }
            while (valid == (int)need.size()) {      // 窗口已覆盖 t，尽量收缩
                if (right - left + 1 < minLen) {
                    start = left;
                    minLen = right - left + 1;
                }
                char d = s[left++];
                if (need.count(d)) {
                    if (win[d] == need[d]) valid--;  // 收缩导致该字符不够了
                    win[d]--;
                }
            }
        }
        return minLen == INT_MAX ? "" : s.substr(start, minLen);
    }
};

class Solution {
public:
    int maxSubArray(vector<int>& nums) {
        int ans = nums[0];
        int pre = nums[0];  // pre：以当前元素结尾的最大子数组和
        for (int i = 1; i < (int)nums.size(); i++) {
            pre = max(pre + nums[i], nums[i]);  // 前缀为负是"负资产"，不如从头开始
            ans = max(ans, pre);
        }
        return ans;
    }
};

class Solution {
public:
    vector<vector<int>> merge(vector<vector<int>>& intervals) {
        sort(intervals.begin(), intervals.end());  // 默认字典序即按左端点排序
        vector<vector<int>> ans;
        for (auto& p : intervals) {
            if (!ans.empty() && p[0] <= ans.back()[1])      // 与上一块重叠/相接
                ans.back()[1] = max(ans.back()[1], p[1]);   // 扩展右端
            else
                ans.push_back(p);
        }
        return ans;
    }
};

class Solution {
public:
    void rotate(vector<int>& nums, int k) {
        int n = nums.size();
        k %= n;                                  // k 可能大于 n，先取模
        reverse(nums.begin(), nums.end());       // 1. 整体翻转
        reverse(nums.begin(), nums.begin() + k); // 2. 翻转前 k 个
        reverse(nums.begin() + k, nums.end());   // 3. 翻转后 n-k 个
    }
};

class Solution {
public:
    vector<int> productExceptSelf(vector<int>& nums) {
        int n = nums.size();
        vector<int> ans(n, 1);
        int pre = 1;
        for (int i = 0; i < n; i++) {  // 第一趟：ans[i] = nums[0..i-1] 的乘积
            ans[i] = pre;
            pre *= nums[i];
        }
        int suf = 1;
        for (int i = n - 1; i >= 0; i--) {  // 第二趟：再乘 nums[i+1..n-1] 的乘积
            ans[i] *= suf;
            suf *= nums[i];
        }
        return ans;
    }
};

class Solution {
public:
    int firstMissingPositive(vector<int>& nums) {
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            // 原地哈希：把值 v (1<=v<=n) 换到下标 v-1，直到当前位置放对或换不动
            while (nums[i] >= 1 && nums[i] <= n && nums[nums[i] - 1] != nums[i])
                swap(nums[i], nums[nums[i] - 1]);
        }
        for (int i = 0; i < n; i++)
            if (nums[i] != i + 1) return i + 1;
        return n + 1;
    }
};

class Solution {
public:
    void setZeroes(vector<vector<int>>& matrix) {
        int m = matrix.size(), n = matrix[0].size();
        bool firstRow = false, firstCol = false;
        for (int j = 0; j < n; j++)
            if (matrix[0][j] == 0) firstRow = true;  // 先记下首行是否本来就有 0
        for (int i = 0; i < m; i++)
            if (matrix[i][0] == 0) firstCol = true;
        for (int i = 1; i < m; i++)
            for (int j = 1; j < n; j++)
                if (matrix[i][j] == 0)
                    matrix[i][0] = matrix[0][j] = 0;  // 征用首行首列做标记
        for (int i = 1; i < m; i++)
            for (int j = 1; j < n; j++)
                if (matrix[i][0] == 0 || matrix[0][j] == 0)
                    matrix[i][j] = 0;                 // 按标记置零内部
        if (firstRow)
            for (int j = 0; j < n; j++) matrix[0][j] = 0;  // 最后处理首行
        if (firstCol)
            for (int i = 0; i < m; i++) matrix[i][0] = 0;  // 最后处理首列
    }
};

class Solution {
public:
    vector<int> spiralOrder(vector<vector<int>>& matrix) {
        int top = 0, bottom = matrix.size() - 1;
        int left = 0, right = matrix[0].size() - 1;
        vector<int> ans;
        while (true) {
            for (int j = left; j <= right; j++) ans.push_back(matrix[top][j]);    // 左→右
            if (++top > bottom) break;
            for (int i = top; i <= bottom; i++) ans.push_back(matrix[i][right]);  // 上→下
            if (--right < left) break;
            for (int j = right; j >= left; j--) ans.push_back(matrix[bottom][j]); // 右→左
            if (--bottom < top) break;
            for (int i = bottom; i >= top; i--) ans.push_back(matrix[i][left]);   // 下→上
            if (++left > right) break;
        }
        return ans;
    }
};

class Solution {
public:
    void rotate(vector<vector<int>>& matrix) {
        int n = matrix.size();
        for (int i = 0; i < n; i++)             // 1. 沿主对角线转置
            for (int j = 0; j < i; j++)
                swap(matrix[i][j], matrix[j][i]);
        for (auto& row : matrix)                // 2. 每行水平翻转
            reverse(row.begin(), row.end());
    }
};

class Solution {
public:
    bool searchMatrix(vector<vector<int>>& matrix, int target) {
        int i = 0, j = matrix[0].size() - 1;  // 从右上角出发
        while (i < (int)matrix.size() && j >= 0) {
            if (matrix[i][j] == target) return true;
            if (matrix[i][j] > target) j--;   // 大于 target：本行右侧全排除，左移
            else i++;                         // 小于 target：本列上方全排除，下移
        }
        return false;
    }
};

class Solution {
public:
    ListNode *getIntersectionNode(ListNode *headA, ListNode *headB) {
        ListNode *p = headA, *q = headB;
        while (p != q) {
            p = p ? p->next : headB;   // 走到头就换道
            q = q ? q->next : headA;
        }
        return p;                      // 相交返回交点，不相交同时为空
    }
};

class Solution {
public:
    ListNode* reverseList(ListNode* head) {
        ListNode *prev = nullptr, *cur = head;
        while (cur) {
            ListNode* nxt = cur->next; // 先暂存后继，防止断链
            cur->next = prev;          // 改向
            prev = cur;
            cur = nxt;
        }
        return prev;
    }
};

class Solution {
    ListNode* reverse(ListNode* head) {          // 复用 206 模板
        ListNode *prev = nullptr, *cur = head;
        while (cur) {
            ListNode* nxt = cur->next;
            cur->next = prev;
            prev = cur;
            cur = nxt;
        }
        return prev;
    }
public:
    bool isPalindrome(ListNode* head) {
        ListNode *slow = head, *fast = head;
        while (fast->next && fast->next->next) { // slow 停在前半段末尾
            slow = slow->next;
            fast = fast->next->next;
        }
        ListNode *p1 = head, *p2 = reverse(slow->next);
        while (p2) {                             // 用较短的后半段做条件
            if (p1->val != p2->val) return false;
            p1 = p1->next;
            p2 = p2->next;
        }
        return true;
    }
};

class Solution {
public:
    bool hasCycle(ListNode *head) {
        ListNode *slow = head, *fast = head;
        while (fast && fast->next) {
            slow = slow->next;
            fast = fast->next->next;
            if (slow == fast) return true;  // 环内追上
        }
        return false;                       // fast 到头，无环
    }
};

class Solution {
public:
    ListNode *detectCycle(ListNode *head) {
        ListNode *slow = head, *fast = head;
        while (fast && fast->next) {
            slow = slow->next;
            fast = fast->next->next;
            if (slow == fast) {            // 相遇：从头再走
                ListNode* p = head;
                while (p != slow) {
                    p = p->next;
                    slow = slow->next;
                }
                return p;                  // 再次相遇处即入环口
            }
        }
        return nullptr;                    // 无环
    }
};

class Solution {
public:
    ListNode* mergeTwoLists(ListNode* list1, ListNode* list2) {
        ListNode dummy(0);
        ListNode* tail = &dummy;
        while (list1 && list2) {
            if (list1->val <= list2->val) { tail->next = list1; list1 = list1->next; }
            else                          { tail->next = list2; list2 = list2->next; }
            tail = tail->next;
        }
        tail->next = list1 ? list1 : list2; // 接上剩余整段
        return dummy.next;
    }
};

class Solution {
public:
    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
        ListNode dummy(0);
        ListNode* tail = &dummy;
        int carry = 0;
        while (l1 || l2 || carry) {
            int sum = carry;
            if (l1) { sum += l1->val; l1 = l1->next; }
            if (l2) { sum += l2->val; l2 = l2->next; }
            carry = sum / 10;
            tail->next = new ListNode(sum % 10); // 新建节点存本位
            tail = tail->next;
        }
        return dummy.next;
    }
};

class Solution {
public:
    ListNode* removeNthFromEnd(ListNode* head, int n) {
        ListNode dummy(0, head);
        ListNode *fast = &dummy, *slow = &dummy;
        for (int i = 0; i < n; i++) fast = fast->next; // fast 先走 n 步
        while (fast->next) {          // fast 停在最后一个节点
            fast = fast->next;
            slow = slow->next;
        }
        ListNode* del = slow->next;   // slow 即被删节点的前驱
        slow->next = del->next;
        delete del;
        return dummy.next;
    }
};

class Solution {
public:
    ListNode* swapPairs(ListNode* head) {
        ListNode dummy(0, head);
        ListNode* prev = &dummy;
        while (prev->next && prev->next->next) {
            ListNode* a = prev->next;
            ListNode* b = a->next;
            a->next = b->next;  // 先保存后继
            b->next = a;        // b 指回 a
            prev->next = b;     // 前驱改接 b
            prev = a;           // a 是交换后的组尾
        }
        return dummy.next;
    }
};

class Solution {
public:
    ListNode* reverseKGroup(ListNode* head, int k) {
        ListNode dummy(0, head);
        ListNode* groupPrev = &dummy;
        while (true) {
            // 从 groupPrev 向后数 k 个，kth 为本组最后一个
            ListNode* kth = groupPrev;
            for (int i = 0; i < k && kth; i++) kth = kth->next;
            if (!kth) break;                  // 不足 k 个，保持原序
            ListNode* groupNext = kth->next;
            // 反转 [groupPrev->next, kth]
            ListNode *prev = groupNext, *cur = groupPrev->next;
            while (cur != groupNext) {
                ListNode* nxt = cur->next;
                cur->next = prev;
                prev = cur;
                cur = nxt;
            }
            ListNode* newTail = groupPrev->next; // 原组头，反转后成组尾
            groupPrev->next = kth;               // 接上新组头
            groupPrev = newTail;                 // 进入下一组
        }
        return dummy.next;
    }
};

class Solution {
public:
    Node* copyRandomList(Node* head) {
        if (!head) return nullptr;
        unordered_map<Node*, Node*> mp; // 原节点 -> 新节点
        for (Node* cur = head; cur; cur = cur->next)
            mp[cur] = new Node(cur->val);
        for (Node* cur = head; cur; cur = cur->next) {
            mp[cur]->next   = mp[cur->next];    // nullptr 也被映射为 nullptr
            mp[cur]->random = mp[cur->random];
        }
        return mp[head];
    }
};

class Solution {
    ListNode* middle(ListNode* head) {      // slow 停在左半段最后一个节点
        ListNode *slow = head, *fast = head->next;
        while (fast && fast->next) {
            slow = slow->next;
            fast = fast->next->next;
        }
        return slow;
    }
    ListNode* merge(ListNode* a, ListNode* b) { // 复用 21 题模板
        ListNode dummy(0);
        ListNode* tail = &dummy;
        while (a && b) {
            if (a->val <= b->val) { tail->next = a; a = a->next; }
            else                  { tail->next = b; b = b->next; }
            tail = tail->next;
        }
        tail->next = a ? a : b;
        return dummy.next;
    }
public:
    ListNode* sortList(ListNode* head) {
        if (!head || !head->next) return head; // 空或单节点已有序
        ListNode* mid = middle(head);
        ListNode* right = mid->next;
        mid->next = nullptr;                   // 断开成两半
        return merge(sortList(head), sortList(right));
    }
};

class Solution {
public:
    ListNode* mergeKLists(vector<ListNode*>& lists) {
        auto cmp = [](ListNode* a, ListNode* b) { return a->val > b->val; }; // 小顶堆
        priority_queue<ListNode*, vector<ListNode*>, decltype(cmp)> pq(cmp);
        for (ListNode* node : lists)
            if (node) pq.push(node);
        ListNode dummy(0);
        ListNode* tail = &dummy;
        while (!pq.empty()) {
            ListNode* node = pq.top(); pq.pop();
            tail->next = node;
            tail = node;
            if (node->next) pq.push(node->next); // 补充该链的下一个
        }
        tail->next = nullptr;
        return dummy.next;
    }
};

class LRUCache {
    struct DNode {
        int key, val;
        DNode *prev, *next;
        DNode(int k = 0, int v = 0) : key(k), val(v), prev(nullptr), next(nullptr) {}
    };
    int cap;
    unordered_map<int, DNode*> mp; // key -> 节点
    DNode *head, *tail;            // 哨兵：head 侧最新，tail 侧最旧

    void remove(DNode* node) {     // 摘除任意位置的节点
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }
    void pushFront(DNode* node) {  // 头插为最新
        node->next = head->next;
        node->prev = head;
        head->next->prev = node;
        head->next = node;
    }
    void moveToHead(DNode* node) { remove(node); pushFront(node); }

public:
    LRUCache(int capacity) : cap(capacity) {
        head = new DNode();
        tail = new DNode();
        head->next = tail;         // 空链表：head <-> tail
        tail->prev = head;
    }
    int get(int key) {
        auto it = mp.find(key);
        if (it == mp.end()) return -1;
        moveToHead(it->second);    // 命中即提为最新
        return it->second->val;
    }
    void put(int key, int value) {
        auto it = mp.find(key);
        if (it != mp.end()) {      // 已存在：更新并提前，不走淘汰
            it->second->val = value;
            moveToHead(it->second);
            return;
        }
        if ((int)mp.size() == cap) {          // 满则淘汰最旧
            DNode* old = tail->prev;
            remove(old);
            mp.erase(old->key);    // 先用 old->key，再 delete
            delete old;
        }
        DNode* node = new DNode(key, value);
        mp[key] = node;
        pushFront(node);
    }
};

/* ========== 写法一：递归 ========== */
class Solution {
public:
    void dfs(TreeNode* node, vector<int>& res) {
        if (!node) return;
        dfs(node->left, res);           // 左
        res.push_back(node->val);       // 根
        dfs(node->right, res);          // 右
    }
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> res;
        dfs(root, res);
        return res;
    }
};

/* ========== 写法二：迭代（显式栈模拟递归）========== */
class Solution {
public:
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> res;
        stack<TreeNode*> st;
        TreeNode* cur = root;
        while (cur || !st.empty()) {
            while (cur) {               // 沿左链一路入栈
                st.push(cur);
                cur = cur->left;
            }
            cur = st.top(); st.pop();   // 弹出最左节点并访问
            res.push_back(cur->val);
            cur = cur->right;           // 转向右子树
        }
        return res;
    }
};

class Solution {
public:
    int maxDepth(TreeNode* root) {
        if (!root) return 0;                        // 递归边界：空树深度 0
        return 1 + max(maxDepth(root->left), maxDepth(root->right));
    }
};

class Solution {
public:
    TreeNode* invertTree(TreeNode* root) {
        if (!root) return nullptr;
        swap(root->left, root->right);   // 交换左右子树（指针整体互换）
        invertTree(root->left);
        invertTree(root->right);
        return root;
    }
};

class Solution {
public:
    bool check(TreeNode* a, TreeNode* b) {   // 判断 a、b 两棵子树是否互为镜像
        if (!a && !b) return true;           // 都空：对称
        if (!a || !b || a->val != b->val) return false;  // 一空一非空或值不等
        return check(a->left, b->right) && check(a->right, b->left);
    }
    bool isSymmetric(TreeNode* root) {
        return !root || check(root->left, root->right);
    }
};

class Solution {
public:
    int ans = 0;
    int depth(TreeNode* node) {              // 返回子树深度，顺便更新直径
        if (!node) return 0;
        int l = depth(node->left);
        int r = depth(node->right);
        ans = max(ans, l + r);               // 经过该节点的路径长 = 左深 + 右深（边数）
        return max(l, r) + 1;                // 向上提供的深度
    }
    int diameterOfBinaryTree(TreeNode* root) {
        depth(root);
        return ans;
    }
};

class Solution {
public:
    vector<vector<int>> levelOrder(TreeNode* root) {
        vector<vector<int>> res;
        if (!root) return res;
        queue<TreeNode*> q;
        q.push(root);
        while (!q.empty()) {
            int sz = q.size();               // 关键：先固定本层节点数
            vector<int> level;
            for (int i = 0; i < sz; i++) {
                TreeNode* node = q.front(); q.pop();
                level.push_back(node->val);
                if (node->left) q.push(node->left);
                if (node->right) q.push(node->right);
            }
            res.push_back(move(level));
        }
        return res;
    }
};

class Solution {
public:
    TreeNode* build(vector<int>& nums, int l, int r) {   // 闭区间 [l, r]
        if (l > r) return nullptr;
        int mid = l + (r - l) / 2;       // 取中点作根，保证左右规模平衡
        TreeNode* node = new TreeNode(nums[mid]);
        node->left = build(nums, l, mid - 1);
        node->right = build(nums, mid + 1, r);
        return node;
    }
    TreeNode* sortedArrayToBST(vector<int>& nums) {
        return build(nums, 0, (int)nums.size() - 1);
    }
};

class Solution {
public:
    bool check(TreeNode* node, long long lo, long long hi) { // 节点值须落在开区间 (lo, hi)
        if (!node) return true;
        if (node->val <= lo || node->val >= hi) return false;
        return check(node->left, lo, node->val)       // 左子树上界收紧
            && check(node->right, node->val, hi);     // 右子树下界收紧
    }
    bool isValidBST(TreeNode* root) {
        return check(root, LLONG_MIN, LLONG_MAX);
    }
};

class Solution {
public:
    int cnt = 0, ans = 0;
    void dfs(TreeNode* node, int k) {
        if (!node || cnt >= k) return;       // cnt >= k：已找到，剪枝
        dfs(node->left, k);                  // 中序：先左
        if (++cnt == k) ans = node->val;     // 第 k 个被访问的节点
        dfs(node->right, k);                 // 再右
    }
    int kthSmallest(TreeNode* root, int k) {
        dfs(root, k);
        return ans;
    }
};

class Solution {
public:
    vector<int> res;
    void dfs(TreeNode* node, int depth) {
        if (!node) return;
        if (depth == (int)res.size())        // 本层首次到达 = 最右节点（根右左顺序保证）
            res.push_back(node->val);
        dfs(node->right, depth + 1);         // 先右后左
        dfs(node->left, depth + 1);
    }
    vector<int> rightSideView(TreeNode* root) {
        dfs(root, 0);
        return res;
    }
};

class Solution {
public:
    void flatten(TreeNode* root) {
        TreeNode* cur = root;
        while (cur) {
            if (cur->left) {
                TreeNode* pre = cur->left;   // 找左子树的最右节点（前驱）
                while (pre->right) pre = pre->right;
                pre->right = cur->right;     // 右子树挂到前驱的右边
                cur->right = cur->left;      // 左子树整体搬到右边
                cur->left = nullptr;
            }
            cur = cur->right;                // 继续处理下一个节点
        }
    }
};

class Solution {
public:
    unordered_map<int, int> pos;         // 中序值 -> 下标，O(1) 定位根
    TreeNode* build(vector<int>& pre, int pl, int pr, int il, int ir) {
        if (pl > pr) return nullptr;
        TreeNode* root = new TreeNode(pre[pl]);   // 前序首元素是根
        int k = pos[pre[pl]];                     // 根在中序中的位置
        int leftLen = k - il;                     // 左子树节点数
        root->left  = build(pre, pl + 1, pl + leftLen, il, k - 1);
        root->right = build(pre, pl + leftLen + 1, pr, k + 1, ir);
        return root;
    }
    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        int n = preorder.size();
        for (int i = 0; i < n; i++) pos[inorder[i]] = i;
        return build(preorder, 0, n - 1, 0, n - 1);
    }
};

class Solution {
public:
    unordered_map<long long, int> cnt;   // 前缀和 -> 出现次数
    long long target;
    int ans = 0;

    void dfs(TreeNode* node, long long cur) {    // cur：根到当前节点的前缀和
        if (!node) return;
        cur += node->val;
        auto it = cnt.find(cur - target);        // 祖先中前缀和为 cur-target 的个数
        if (it != cnt.end()) ans += it->second;  // 每个都对应一条以当前节点结尾的路径
        cnt[cur]++;                              // 登记当前前缀和
        dfs(node->left, cur);
        dfs(node->right, cur);
        cnt[cur]--;                              // 回溯：撤销，只保留祖先路径上的前缀和
    }

    int pathSum(TreeNode* root, int targetSum) {
        target = targetSum;
        cnt[0] = 1;                              // 空前缀：覆盖"从根开始"的路径
        dfs(root, 0);
        return ans;
    }
};

class Solution {
public:
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        if (!root || root == p || root == q) return root;  // 命中空或目标节点
        TreeNode* left  = lowestCommonAncestor(root->left, p, q);
        TreeNode* right = lowestCommonAncestor(root->right, p, q);
        if (left && right) return root;      // p、q 分居两侧：当前节点即 LCA
        return left ? left : right;          // 否则向上传递找到的那一个
    }
};

class Solution {
public:
    int ans = INT_MIN;
    int gain(TreeNode* node) {               // 返回从 node 出发向下的最大贡献
        if (!node) return 0;
        int l = max(gain(node->left), 0);    // 子树贡献为负则舍弃（不选这条边）
        int r = max(gain(node->right), 0);
        ans = max(ans, node->val + l + r);   // 以 node 为"拐点"的完整路径
        return node->val + max(l, r);        // 向父亲只能延伸一条边
    }
    int maxPathSum(TreeNode* root) {
        gain(root);
        return ans;
    }
};

class Solution {
public:
    int numIslands(vector<vector<char>>& grid) {
        int m = grid.size(), n = grid[0].size(), cnt = 0;
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j)
                if (grid[i][j] == '1') {
                    ++cnt;
                    dfs(grid, i, j);          // 沉掉整个连通块
                }
        return cnt;
    }
private:
    void dfs(vector<vector<char>>& grid, int i, int j) {
        if (i < 0 || i >= grid.size() || j < 0 || j >= grid[0].size() || grid[i][j] != '1')
            return;
        grid[i][j] = '0';                     // 标记：直接改成水
        dfs(grid, i + 1, j);
        dfs(grid, i - 1, j);
        dfs(grid, i, j + 1);
        dfs(grid, i, j - 1);
    }
};

class Solution {
public:
    int orangesRotting(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size(), fresh = 0;
        queue<pair<int, int>> q;
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j)
                if (grid[i][j] == 2) q.emplace(i, j);   // 多源：所有烂橘子同时入队
                else if (grid[i][j] == 1) ++fresh;
        if (fresh == 0) return 0;                       // 没有新鲜橘子
        int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1}, minutes = 0;
        while (!q.empty() && fresh > 0) {
            ++minutes;                                  // 每处理一层 = 过一分钟
            for (int sz = q.size(); sz > 0; --sz) {
                auto [x, y] = q.front(); q.pop();
                for (int d = 0; d < 4; ++d) {
                    int nx = x + dx[d], ny = y + dy[d];
                    if (nx < 0 || nx >= m || ny < 0 || ny >= n || grid[nx][ny] != 1) continue;
                    grid[nx][ny] = 2;                   // 入队时立刻变烂，防止重复入队
                    --fresh;
                    q.emplace(nx, ny);
                }
            }
        }
        return fresh == 0 ? minutes : -1;               // 还有新鲜的 = 永远烂不完
    }
};

class Solution {
public:
    bool canFinish(int numCourses, vector<vector<int>>& prerequisites) {
        vector<vector<int>> g(numCourses);
        vector<int> indeg(numCourses, 0);
        for (auto& p : prerequisites) {
            g[p[1]].push_back(p[0]);        // 边：先修 p[1] → 才能修 p[0]
            ++indeg[p[0]];
        }
        queue<int> q;
        for (int i = 0; i < numCourses; ++i)
            if (indeg[i] == 0) q.push(i);   // 入度为 0 的先入队
        int taken = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            ++taken;
            for (int v : g[u])
                if (--indeg[v] == 0) q.push(v);
        }
        return taken == numCourses;         // 能全部出队 ⇔ 无环
    }
};

class Trie {
private:
    Trie* ch[26]{};      // 26 个子节点指针，{} 保证初始为 nullptr
    bool isEnd = false;  // 是否有单词在此结束

    Trie* find(const string& s) {           // 沿字符走到底，返回到达的节点
        Trie* node = this;
        for (char c : s) {
            node = node->ch[c - 'a'];
            if (!node) return nullptr;
        }
        return node;
    }

public:
    Trie() {}

    void insert(string word) {
        Trie* node = this;
        for (char c : word) {
            int i = c - 'a';
            if (!node->ch[i]) node->ch[i] = new Trie();  // 缺路就建
            node = node->ch[i];
        }
        node->isEnd = true;
    }

    bool search(string word) {
        Trie* node = find(word);
        return node && node->isEnd;      // 必须是完整单词
    }

    bool startsWith(string prefix) {
        return find(prefix) != nullptr;  // 路径存在即可
    }
};

class Solution {
public:
    vector<vector<int>> permute(vector<int>& nums) {
        vector<vector<int>> ans;
        vector<int> path;
        vector<bool> used(nums.size(), false);
        dfs(nums, used, path, ans);
        return ans;
    }
private:
    void dfs(vector<int>& nums, vector<bool>& used, vector<int>& path, vector<vector<int>>& ans) {
        if (path.size() == nums.size()) {   // 排列凑满，收集
            ans.push_back(path);
            return;
        }
        for (int i = 0; i < nums.size(); ++i) {
            if (used[i]) continue;
            used[i] = true;                 // 1. 选择
            path.push_back(nums[i]);
            dfs(nums, used, path, ans);     // 2. 递归
            path.pop_back();                // 3. 撤销：恢复现场
            used[i] = false;
        }
    }
};

class Solution {
public:
    vector<vector<int>> subsets(vector<int>& nums) {
        vector<vector<int>> ans;
        vector<int> path;
        dfs(nums, 0, path, ans);
        return ans;
    }
private:
    void dfs(vector<int>& nums, int start, vector<int>& path, vector<vector<int>>& ans) {
        ans.push_back(path);            // 每个节点（每条路径前缀）都是一个子集
        for (int i = start; i < nums.size(); ++i) {
            path.push_back(nums[i]);    // 选择
            dfs(nums, i + 1, path, ans);// 传 i+1：后面的元素才可再选
            path.pop_back();            // 撤销
        }
    }
};

class Solution {
public:
    vector<string> letterCombinations(string digits) {
        if (digits.empty()) return {};      // 空串不能进回溯，否则会收到 ""
        const vector<string> mp = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
        string path;
        vector<string> ans;
        dfs(digits, 0, mp, path, ans);
        return ans;
    }
private:
    void dfs(const string& digits, int idx, const vector<string>& mp, string& path, vector<string>& ans) {
        if (idx == digits.size()) {
            ans.push_back(path);
            return;
        }
        for (char c : mp[digits[idx] - '0']) {  // 该按键的每个字母都是一个分支
            path.push_back(c);
            dfs(digits, idx + 1, mp, path, ans);
            path.pop_back();
        }
    }
};

class Solution {
public:
    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        vector<vector<int>> ans;
        vector<int> path;
        dfs(candidates, 0, target, path, ans);
        return ans;
    }
private:
    void dfs(vector<int>& candidates, int start, int remain, vector<int>& path, vector<vector<int>>& ans) {
        if (remain == 0) {              // 恰好凑出，收集
            ans.push_back(path);
            return;
        }
        for (int i = start; i < candidates.size(); ++i) {
            if (candidates[i] > remain) continue;   // 剪枝：这个数放不下
            path.push_back(candidates[i]);
            dfs(candidates, i, remain - candidates[i], path, ans); // 传 i：可重复选
            path.pop_back();
        }
    }
};

class Solution {
public:
    vector<string> generateParenthesis(int n) {
        vector<string> ans;
        string path;
        dfs(n, 0, 0, path, ans);
        return ans;
    }
private:
    void dfs(int n, int open, int close, string& path, vector<string>& ans) {
        if (path.size() == 2 * n) {
            ans.push_back(path);
            return;
        }
        if (open < n) {                 // 还能放左括号
            path.push_back('(');
            dfs(n, open + 1, close, path, ans);
            path.pop_back();
        }
        if (close < open) {             // 右括号数量不能超过左括号
            path.push_back(')');
            dfs(n, open, close + 1, path, ans);
            path.pop_back();
        }
    }
};

class Solution {
public:
    bool exist(vector<vector<char>>& board, string word) {
        for (int i = 0; i < board.size(); ++i)
            for (int j = 0; j < board[0].size(); ++j)
                if (dfs(board, word, i, j, 0)) return true;
        return false;
    }
private:
    bool dfs(vector<vector<char>>& board, const string& word, int i, int j, int k) {
        if (i < 0 || i >= board.size() || j < 0 || j >= board[0].size() || board[i][j] != word[k])
            return false;
        if (k == word.size() - 1) return true;   // 最后一位也匹配
        board[i][j] = '#';                       // 选择：占位，防同路径重复使用
        bool found = dfs(board, word, i + 1, j, k + 1) ||
                     dfs(board, word, i - 1, j, k + 1) ||
                     dfs(board, word, i, j + 1, k + 1) ||
                     dfs(board, word, i, j - 1, k + 1);
        board[i][j] = word[k];                   // 撤销：恢复现场
        return found;
    }
};

class Solution {
public:
    vector<vector<string>> partition(string s) {
        int n = s.size();
        vector<vector<bool>> isPal(n, vector<bool>(n, false));  // isPal[i][j]: s[i..j] 是否回文
        for (int i = n - 1; i >= 0; --i)
            for (int j = i; j < n; ++j)
                isPal[i][j] = s[i] == s[j] && (j - i < 2 || isPal[i + 1][j - 1]);
        vector<vector<string>> ans;
        vector<string> path;
        dfs(s, 0, isPal, path, ans);
        return ans;
    }
private:
    void dfs(const string& s, int start, vector<vector<bool>>& isPal,
             vector<string>& path, vector<vector<string>>& ans) {
        if (start == s.size()) {
            ans.push_back(path);
            return;
        }
        for (int end = start; end < s.size(); ++end) {
            if (!isPal[start][end]) continue;    // 前缀不是回文，剪掉
            path.push_back(s.substr(start, end - start + 1));  // 选择：切出一段
            dfs(s, end + 1, isPal, path, ans);   // 下一段从 end+1 开始
            path.pop_back();                     // 撤销
        }
    }
};

class Solution {
public:
    vector<vector<string>> solveNQueens(int n) {
        vector<vector<string>> ans;
        vector<string> board(n, string(n, '.'));
        vector<bool> col(n, false), diag1(2 * n - 1, false), diag2(2 * n - 1, false);
        dfs(board, 0, col, diag1, diag2, ans);
        return ans;
    }
private:
    void dfs(vector<string>& board, int row, vector<bool>& col, vector<bool>& diag1,
             vector<bool>& diag2, vector<vector<string>>& ans) {
        int n = board.size();
        if (row == n) {
            ans.push_back(board);           // 棋盘即答案格式，直接收集
            return;
        }
        for (int c = 0; c < n; ++c) {
            int d1 = row + c;               // "/" 方向对角线编号
            int d2 = row - c + n - 1;       // "\" 方向，+n-1 平移防负下标
            if (col[c] || diag1[d1] || diag2[d2]) continue;
            board[row][c] = 'Q';            // 选择
            col[c] = diag1[d1] = diag2[d2] = true;
            dfs(board, row + 1, col, diag1, diag2, ans);
            col[c] = diag1[d1] = diag2[d2] = false;  // 撤销：恢复现场
            board[row][c] = '.';
        }
    }
};

class Solution {
public:
    int searchInsert(vector<int>& nums, int target) {
        int l = 0, r = nums.size();              // 左闭右开 [l, r)
        while (l < r) {
            int mid = l + (r - l) / 2;           // 防止 l+r 溢出
            if (nums[mid] < target) l = mid + 1; // 答案在 (mid, r) 中
            else r = mid;                        // mid 可能是答案，不能丢
        }
        return l;                                // 第一个 >= target 的下标
    }
};

class Solution {
public:
    bool searchMatrix(vector<vector<int>>& matrix, int target) {
        int m = matrix.size(), n = matrix[0].size();
        int l = 0, r = m * n - 1;                // 闭区间 [l, r]
        while (l <= r) {
            int mid = l + (r - l) / 2;
            int val = matrix[mid / n][mid % n];  // 一维下标还原成二维坐标
            if (val == target) return true;
            else if (val < target) l = mid + 1;
            else r = mid - 1;
        }
        return false;
    }
};

class Solution {
public:
    vector<int> searchRange(vector<int>& nums, int target) {
        int first = lowerBound(nums, target);
        if (first == (int)nums.size() || nums[first] != target) return {-1, -1};
        int last = upperBound(nums, target) - 1; // 第一个 > target 的位置再退一格
        return {first, last};
    }
private:
    // 第一个 >= x 的下标（不存在则为 n）
    int lowerBound(vector<int>& nums, int x) {
        int l = 0, r = nums.size();
        while (l < r) {
            int mid = l + (r - l) / 2;
            if (nums[mid] < x) l = mid + 1;
            else r = mid;
        }
        return l;
    }
    // 第一个 > x 的下标（不存在则为 n）
    int upperBound(vector<int>& nums, int x) {
        int l = 0, r = nums.size();
        while (l < r) {
            int mid = l + (r - l) / 2;
            if (nums[mid] <= x) l = mid + 1;     // 与 lowerBound 唯一区别：多带等号
            else r = mid;
        }
        return l;
    }
};

class Solution {
public:
    int search(vector<int>& nums, int target) {
        int l = 0, r = nums.size() - 1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (nums[mid] == target) return mid;
            if (nums[l] <= nums[mid]) {                          // 左半段 [l, mid] 有序
                if (nums[l] <= target && target < nums[mid]) r = mid - 1;
                else l = mid + 1;
            } else {                                             // 右半段 [mid, r] 有序
                if (nums[mid] < target && target <= nums[r]) l = mid + 1;
                else r = mid - 1;
            }
        }
        return -1;
    }
};

class Solution {
public:
    int findMin(vector<int>& nums) {
        int l = 0, r = nums.size() - 1;
        while (l < r) {
            int mid = l + (r - l) / 2;           // mid < r 恒成立，r = mid 不会死循环
            if (nums[mid] > nums[r]) l = mid + 1; // 拐点在右侧，mid 可排除
            else r = mid;                         // [mid, r] 有序，mid 可能是答案
        }
        return nums[l];
    }
};

class Solution {
public:
    double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {
        if (nums1.size() > nums2.size()) return findMedianSortedArrays(nums2, nums1);
        int m = nums1.size(), n = nums2.size();
        int leftCnt = (m + n + 1) / 2;              // 分割线左侧应有的元素个数
        // 在 [0, m] 中找最大的 i 满足 nums1[i-1] <= nums2[j]，其中 j = leftCnt - i
        int l = 0, r = m;
        while (l < r) {
            int i = l + (r - l + 1) / 2;            // 取右中位，配合 l = i 防死循环
            int j = leftCnt - i;
            if (nums1[i - 1] <= nums2[j]) l = i;    // 分割线可右移
            else r = i - 1;
        }
        int i = l, j = leftCnt - i;
        int L1 = (i == 0) ? INT_MIN : nums1[i - 1]; // 左半各侧最大值，越界用 -inf
        int L2 = (j == 0) ? INT_MIN : nums2[j - 1];
        int R1 = (i == m) ? INT_MAX : nums1[i];     // 右半各侧最小值，越界用 +inf
        int R2 = (j == n) ? INT_MAX : nums2[j];
        if ((m + n) % 2 == 1) return max(L1, L2);
        return (max(L1, L2) + min(R1, R2)) / 2.0;
    }
};

class Solution {
public:
    bool isValid(string s) {
        if (s.size() % 2) return false;  // 奇数长度必不匹配，提前剪枝
        stack<char> st;                  // 存"期望出现的右括号"
        for (char c : s) {
            if (c == '(') st.push(')');
            else if (c == '[') st.push(']');
            else if (c == '{') st.push('}');
            else if (st.empty() || st.top() != c) return false; // 栈空或不匹配
            else st.pop();
        }
        return st.empty();               // 有剩余则存在未闭合的左括号
    }
};

class MinStack {
    stack<int> st;   // 主栈
    stack<int> mn;   // mn.top() = 主栈当前所有元素的最小值
public:
    MinStack() {}

    void push(int val) {
        st.push(val);
        mn.push(mn.empty() ? val : min(val, mn.top())); // 同步维护最小值
    }

    void pop() {
        st.pop();
        mn.pop();        // 同步弹出，自动"回退"到次小值
    }

    int top() { return st.top(); }

    int getMin() { return mn.top(); }
};

class Solution {
public:
    string decodeString(string s) {
        stack<int> numSt;     // 倍数栈
        stack<string> strSt;  // 保存各层"进入内层前"的外层串
        string cur;           // 当前层已解码的串
        int num = 0;
        for (char c : s) {
            if (isdigit(c)) {
                num = num * 10 + (c - '0');   // 倍数可能是多位数
            } else if (c == '[') {
                numSt.push(num); num = 0;     // 保存倍数，进入新层
                strSt.push(cur); cur = "";    // 保存外层串，另起当前层
            } else if (c == ']') {
                int k = numSt.top(); numSt.pop();
                string tmp;
                for (int t = 0; t < k; t++) tmp += cur; // 当前层重复 k 次
                cur = strSt.top() + tmp; strSt.pop();   // 接回外层串
            } else {
                cur += c;                     // 普通字母直接累积
            }
        }
        return cur;
    }
};

class Solution {
public:
    vector<int> dailyTemperatures(vector<int>& temperatures) {
        int n = temperatures.size();
        vector<int> ans(n, 0);            // 默认 0：右侧没有更大温度
        stack<int> st;                    // 单调递减栈，存下标
        for (int i = 0; i < n; i++) {
            while (!st.empty() && temperatures[i] > temperatures[st.top()]) {
                int j = st.top(); st.pop();
                ans[j] = i - j;           // i 是 j 右侧第一个更大元素
            }
            st.push(i);
        }
        return ans;
    }
};

class Solution {
public:
    int largestRectangleArea(vector<int>& heights) {
        int n = heights.size();
        stack<int> st;                    // 单调递增栈，存下标
        st.push(-1);                      // 左边界哨兵
        int ans = 0;
        for (int i = 0; i <= n; i++) {
            int h = (i == n) ? 0 : heights[i]; // 末尾高度 0 哨兵，逼清栈内元素
            while (st.top() != -1 && heights[st.top()] >= h) {
                int height = heights[st.top()]; st.pop();
                int width = i - st.top() - 1;  // 左右开区间内的柱子数
                ans = max(ans, height * width);
            }
            st.push(i);
        }
        return ans;
    }
};

class Solution {
public:
    int findKthLargest(vector<int>& nums, int k) {
        priority_queue<int, vector<int>, greater<int>> pq; // 小顶堆
        for (int x : nums) {
            if ((int)pq.size() < k) {
                pq.push(x);                 // 堆未满，直接入堆
            } else if (x > pq.top()) {
                pq.pop(); pq.push(x);       // 比堆顶大才值得替换
            }
        }
        return pq.top();                    // K 个最大值中最小的那个
    }
};

class Solution {
public:
    vector<int> topKFrequent(vector<int>& nums, int k) {
        unordered_map<int, int> cnt;
        for (int x : nums) cnt[x]++;          // 哈希计数
        // 小顶堆按 (频次, 元素) 比较，只保留频次最高的 K 个
        priority_queue<pair<int, int>, vector<pair<int, int>>,
                       greater<pair<int, int>>> pq;
        for (auto& [val, c] : cnt) {          // C++17 结构化绑定
            pq.push({c, val});
            if ((int)pq.size() > k) pq.pop(); // 淘汰频次最小者
        }
        vector<int> ans;
        while (!pq.empty()) { ans.push_back(pq.top().second); pq.pop(); }
        return ans;
    }
};

class MedianFinder {
    priority_queue<int> left;                             // 大顶堆：较小一半
    priority_queue<int, vector<int>, greater<int>> right; // 小顶堆：较大一半
public:
    MedianFinder() {}

    void addNum(int num) {
        if (left.empty() || num <= left.top()) left.push(num);
        else right.push(num);
        // 平衡：left 允许比 right 多 1，不允许反向失衡
        if (left.size() > right.size() + 1) {
            right.push(left.top()); left.pop();
        } else if (right.size() > left.size()) {
            left.push(right.top()); right.pop();
        }
    }

    double findMedian() {
        if (left.size() > right.size()) return left.top(); // 总数为奇数
        return (left.top() + right.top()) / 2.0;           // 偶数取平均
    }
};

class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int minPrice = INT_MAX, ans = 0;
        for (int p : prices) {
            ans = max(ans, p - minPrice); // 在历史最低点买入、今天卖出
            minPrice = min(minPrice, p);  // 维护历史最低价
        }
        return ans;
    }
};

class Solution {
public:
    bool canJump(vector<int>& nums) {
        int far = 0; // 当前可达的最远下标
        for (int i = 0; i < (int)nums.size(); ++i) {
            if (i > far) return false; // 位置 i 不可达
            far = max(far, i + nums[i]);
            if (far >= (int)nums.size() - 1) return true; // 提前结束
        }
        return true;
    }
};

class Solution {
public:
    int jump(vector<int>& nums) {
        int steps = 0, curEnd = 0, far = 0;
        for (int i = 0; i < (int)nums.size() - 1; ++i) {
            far = max(far, i + nums[i]); // 下一层能到的最远位置
            if (i == curEnd) {           // 走完当前层，必须起跳进入下一层
                ++steps;
                curEnd = far;
            }
        }
        return steps;
    }
};

class Solution {
public:
    vector<int> partitionLabels(string s) {
        int last[26] = {0};
        for (int i = 0; i < (int)s.size(); ++i)
            last[s[i] - 'a'] = i;             // 每个字母最后出现的位置
        vector<int> ans;
        int start = 0, end = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            end = max(end, last[s[i] - 'a']); // 必须覆盖当前字母的最后出现
            if (i == end) {                   // 当前片段闭合
                ans.push_back(end - start + 1);
                start = i + 1;
            }
        }
        return ans;
    }
};

class Solution {
public:
    int climbStairs(int n) {
        int a = 1, b = 1; // f(0)=1, f(1)=1
        for (int i = 2; i <= n; ++i) {
            int c = a + b;
            a = b; b = c;
        }
        return b;
    }
};

class Solution {
public:
    vector<vector<int>> generate(int numRows) {
        vector<vector<int>> ans(numRows);
        for (int i = 0; i < numRows; ++i) {
            ans[i].assign(i + 1, 1); // 每行首尾都是 1
            for (int j = 1; j < i; ++j)
                ans[i][j] = ans[i - 1][j - 1] + ans[i - 1][j];
        }
        return ans;
    }
};

class Solution {
public:
    int rob(vector<int>& nums) {
        int pre = 0, cur = 0; // dp[i-2], dp[i-1]
        for (int x : nums) {
            int t = max(cur, pre + x); // 不偷当前家 / 偷当前家
            pre = cur; cur = t;
        }
        return cur;
    }
};

class Solution {
public:
    int numSquares(int n) {
        vector<int> dp(n + 1, INT_MAX);
        dp[0] = 0;
        for (int i = 1; i * i <= n; ++i)          // 物品：完全平方数
            for (int j = i * i; j <= n; ++j)      // 容量正序：完全背包
                dp[j] = min(dp[j], dp[j - i * i] + 1);
        return dp[n];
    }
};

class Solution {
public:
    int coinChange(vector<int>& coins, int amount) {
        const int INF = amount + 1; // 视作“不可达”，防止溢出
        vector<int> dp(amount + 1, INF);
        dp[0] = 0;
        for (int c : coins)
            for (int j = c; j <= amount; ++j) // 容量正序：每种硬币可重复用
                dp[j] = min(dp[j], dp[j - c] + 1);
        return dp[amount] > amount ? -1 : dp[amount];
    }
};

class Solution {
public:
    bool wordBreak(string s, vector<string>& wordDict) {
        int n = s.size();
        vector<bool> dp(n + 1, false); // dp[i]: 前 i 个字符可拆分
        dp[0] = true;
        unordered_set<string> dict(wordDict.begin(), wordDict.end());
        for (int i = 1; i <= n; ++i)
            for (int j = 0; j < i && !dp[i]; ++j)
                if (dp[j] && dict.count(s.substr(j, i - j)))
                    dp[i] = true;
        return dp[n];
    }
};

class Solution {
public:
    int lengthOfLIS(vector<int>& nums) {
        int n = nums.size();
        vector<int> dp(n, 1); // dp[i]: 以 nums[i] 结尾的 LIS 长度
        int ans = 1;
        for (int i = 1; i < n; ++i) {
            for (int j = 0; j < i; ++j)
                if (nums[j] < nums[i]) dp[i] = max(dp[i], dp[j] + 1);
            ans = max(ans, dp[i]);
        }
        return ans;
    }
};

class Solution {
public:
    int maxProduct(vector<int>& nums) {
        int ans = nums[0], mx = nums[0], mn = nums[0]; // 以当前元素结尾的最大/最小乘积
        for (int i = 1; i < (int)nums.size(); ++i) {
            int x = nums[i];
            if (x < 0) swap(mx, mn); // 负数让最大、最小角色互换
            mx = max(x, mx * x);
            mn = min(x, mn * x);
            ans = max(ans, mx);
        }
        return ans;
    }
};

class Solution {
public:
    bool canPartition(vector<int>& nums) {
        int sum = 0;
        for (int x : nums) sum += x;
        if (sum % 2) return false;   // 总和为奇数不可能平分
        int target = sum / 2;
        vector<bool> dp(target + 1, false); // dp[j]: 能否凑出和 j
        dp[0] = true;
        for (int x : nums)
            for (int j = target; j >= x; --j) // 倒序：0-1 背包每件只用一次
                dp[j] = dp[j] || dp[j - x];
        return dp[target];
    }
};

class Solution {
public:
    int longestValidParentheses(string s) {
        stack<int> st; // 栈底哨兵：最近一个未匹配右括号的下标（初始 -1）
        st.push(-1);
        int ans = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            if (s[i] == '(') {
                st.push(i);
            } else {
                st.pop();                          // 弹出尝试匹配
                if (st.empty()) st.push(i);        // 配不上，i 成为新哨兵
                else ans = max(ans, i - st.top()); // 有效段起点是 st.top() 之后
            }
        }
        return ans;
    }
};

class Solution {
public:
    int uniquePaths(int m, int n) {
        vector<int> dp(n, 1); // 第一行全为 1
        for (int i = 1; i < m; ++i)
            for (int j = 1; j < n; ++j)
                dp[j] += dp[j - 1]; // 上方旧值 + 左方新值
        return dp[n - 1];
    }
};

class Solution {
public:
    int minPathSum(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j) {
                if (i == 0 && j == 0) continue;                    // 起点
                else if (i == 0) grid[i][j] += grid[i][j - 1];     // 首行：只能来自左
                else if (j == 0) grid[i][j] += grid[i - 1][j];     // 首列：只能来自上
                else grid[i][j] += min(grid[i - 1][j], grid[i][j - 1]);
            }
        return grid[m - 1][n - 1];
    }
};

class Solution {
public:
    string longestPalindrome(string s) {
        int n = s.size();
        vector<vector<bool>> dp(n, vector<bool>(n, false)); // dp[i][j]: s[i..j] 是否回文
        int start = 0, len = 1;
        for (int j = 0; j < n; ++j) {
            dp[j][j] = true; // 单字符
            for (int i = 0; i < j; ++i) {
                if (s[i] != s[j]) continue;
                if (j - i < 3 || dp[i + 1][j - 1]) dp[i][j] = true; // 长度≤3 或内部回文
                if (dp[i][j] && j - i + 1 > len) { start = i; len = j - i + 1; }
            }
        }
        return s.substr(start, len);
    }
};

class Solution {
public:
    int longestCommonSubsequence(string text1, string text2) {
        int m = text1.size(), n = text2.size();
        vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0)); // dp[i][j]: 前缀长度 LCS
        for (int i = 1; i <= m; ++i)
            for (int j = 1; j <= n; ++j) {
                if (text1[i - 1] == text2[j - 1])
                    dp[i][j] = dp[i - 1][j - 1] + 1; // 末尾相等：共同取掉
                else
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]); // 丢掉一个末尾
            }
        return dp[m][n];
    }
};

class Solution {
public:
    int minDistance(string word1, string word2) {
        int m = word1.size(), n = word2.size();
        vector<vector<int>> dp(m + 1, vector<int>(n + 1));
        for (int i = 0; i <= m; ++i) dp[i][0] = i; // 全部删除
        for (int j = 0; j <= n; ++j) dp[0][j] = j; // 全部插入
        for (int i = 1; i <= m; ++i)
            for (int j = 1; j <= n; ++j) {
                if (word1[i - 1] == word2[j - 1])
                    dp[i][j] = dp[i - 1][j - 1]; // 末尾相等，无需操作
                else
                    dp[i][j] = min({dp[i - 1][j - 1], // 替换
                                    dp[i - 1][j],     // 删除 word1 末尾
                                    dp[i][j - 1]})    // 插入 word2 末尾
                               + 1;
            }
        return dp[m][n];
    }
};

class Solution {
public:
    int singleNumber(vector<int>& nums) {
        int ans = 0;
        for (int x : nums) ans ^= x;   // 成对的数异或抵消为 0
        return ans;                    // 剩下的即只出现一次的数
    }
};

class Solution {
public:
    int majorityElement(vector<int>& nums) {
        int candidate = 0, cnt = 0;
        for (int x : nums) {
            if (cnt == 0) candidate = x;      // 票数归零，换当前元素当候选人
            cnt += (x == candidate) ? 1 : -1; // 相同 +1，不同 -1（两两抵消）
        }
        return candidate;                     // 出现次数 > n/2 的元素必然存活
    }
};

class Solution {
public:
    void sortColors(vector<int>& nums) {
        int low = 0, i = 0, high = nums.size() - 1;
        while (i <= high) {
            if (nums[i] == 0) {
                swap(nums[i], nums[low]);   // 换来的是 1 或自身，可前进
                ++low; ++i;
            } else if (nums[i] == 2) {
                swap(nums[i], nums[high]);  // 换来的元素未检查，i 原地再判
                --high;
            } else {
                ++i;                        // 1 属于中段，留在原地
            }
        }
    }
};

class Solution {
public:
    void nextPermutation(vector<int>& nums) {
        int n = nums.size();
        int i = n - 2;
        while (i >= 0 && nums[i] >= nums[i + 1]) --i;   // ① 从右找第一个升序对 nums[i] < nums[i+1]
        if (i >= 0) {
            int j = n - 1;
            while (nums[j] <= nums[i]) --j;             // ② 后缀降序，从右找第一个大于 nums[i] 的数
            swap(nums[i], nums[j]);
        }
        reverse(nums.begin() + i + 1, nums.end());      // ③ 反转降序后缀 → 最小排列
    }
};

class Solution {
public:
    int findDuplicate(vector<int>& nums) {
        // 视作链表 i -> nums[i]：重复数 = 环的入口，Floyd 判圈
        int slow = 0, fast = 0;
        do {
            slow = nums[slow];           // 慢指针走一步
            fast = nums[nums[fast]];     // 快指针走两步
        } while (slow != fast);
        slow = 0;                        // 一只指针回到起点
        while (slow != fast) {           // 同速前进，再次相遇即环入口
            slow = nums[slow];
            fast = nums[fast];
        }
        return slow;
    }
};
